import os, sys, json, subprocess

BASE = "storage/shared/atlas/analysis/inquirer_veritas_power_law_sim"

SUMMARY_CANDIDATES = [
    f"{BASE}/power_law_sim_summary_v4.5.1_avg.json",
    f"{BASE}/power_law_sim_summary_v4.5_avg.json",
]
PLOT_CANDIDATES = [
    f"{BASE}/power_law_sim_v4.5.1_avg_plot.png",
    f"{BASE}/power_law_sim_v4.5_avg_plot.png",
]

def first_existing(paths):
    for p in paths:
        if os.path.exists(p):
            return p
    return None

def run_cmd(cmd):
    p = subprocess.run(cmd, capture_output=True, text=True)
    if p.returncode != 0:
        print("STDOUT:", p.stdout)
        print("STDERR:", p.stderr)
        raise SystemExit(p.returncode)
    s = p.stdout.strip()
    try:
        return json.loads(s)
    except Exception:
        return {"raw": s}

summary_path = first_existing(SUMMARY_CANDIDATES)
plot_path = first_existing(PLOT_CANDIDATES)

if not summary_path or not plot_path:
    print(json.dumps({
        "status": "pending",
        "found": {"summary": summary_path is not None, "plot": plot_path is not None},
        "expected_candidates": {"summary": SUMMARY_CANDIDATES, "plot": PLOT_CANDIDATES}
    }, indent=2, ensure_ascii=False))
    sys.exit(0)

cfg = {"env":{"python":"3.10","deps":[]}, "data":[], "outputs":[{"path":summary_path},{"path":plot_path}]}
with open("verify_config.json", "w", encoding="utf-8") as f:
    json.dump(cfg, f, indent=2, ensure_ascii=False)

pref = run_cmd([sys.executable, "storage/shared/agency_lab/repro_template/v2/preflight_static.py",
                "--config", "verify_config.json"])

hash_out = run_cmd([sys.executable, "storage/shared/agency_lab/repro_template/v2/hash_outputs.py",
                    "--config", "verify_config.json", "--out", "verify_config.strict.json"])

ver_strict = run_cmd([sys.executable, "storage/shared/agency_lab/repro_template/v2/verify.py",
                      "--mode", "strict", "--config", "verify_config.strict.json"])

with open("verify_config.strict.json", "r", encoding="utf-8") as f:
    strict_cfg = json.load(f)
shas = [{"path": o.get("path"), "sha256": o.get("sha256")} for o in strict_cfg.get("outputs", [])]

print(json.dumps({
    "status": "verified",
    "picked": {"summary": summary_path, "plot": plot_path},
    "preflight": pref,
    "hash_outputs": hash_out,
    "verify_strict": ver_strict,
    "sha256": shas
}, indent=2, ensure_ascii=False))

